    "audit_result": {
      "property_id": "PROP-56ad1eb2-inv-014",
      "classification": "vulnerability",
      "code_path": "config/params/loader.go::UnmarshalConfig::L56-70",
      "proof_trace": "Config loader performs YAML unmarshaling into BlobSchedule with no validation that MaxBlobsPerBlock entries are <= 4096. This allows misconfigured nodes to accept BlobSchedule values above the SSZ hard limit (MAX_BLOB_COMMITMENTS_PER_BLOCK=4096), creating a protocol-network inconsistency where blocks with >4096 commitments are protocol-valid per verifyBlobCommitmentCount but cannot be SSZ-encoded/decoded for P2P transmission.",
      "attack_scenario": "An attacker distributes a malicious config file with BLOB_SCHEDULE: [{EPOCH: 0, MAX_BLOBS_PER_BLOCK: 5000}]. Nodes loading this config will accept blocks with up to 5000 KZG commitments in verifyBlobCommitmentCount (payload.go:239), but such blocks cannot be transmitted over P2P due to SSZ's 4096 hard limit (conversions_block.go:1367, fieldparams/mainnet.go:29). This causes honest validators to propose valid-but-untransmittable blocks, leading to chain stalls or consensus divergence between nodes using different validation code paths.",
      "checklist_id": "PROP-56ad1eb2-inv-014"
    },
    "text": "All BLOB_SCHEDULE max_blobs_per_block values must be <= MAX_BLOB_COMMITMENTS_PER_BLOCK.",
    "assertion": "forall entry in BLOB_SCHEDULE: entry.max_blobs_per_block <= MAX_BLOB_COMMITMENTS_PER_BLOCK",
    "covers": "SG-001",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

